css:
[data-bz-node="loc-hero-band"]{position:relative;overflow:hidden;background:#141414;text-align:center;padding:88px 48px;}
[data-bz-node="loc-hero-band"]::before{content:"";position:absolute;inset:0;background:rgba(20,20,20,.72);z-index:1;}
[data-bz-node="loc-hero-band"] .bz-block{padding-block:0;}
[data-bz-node="loc-hero-photo-row"]{position:absolute;inset:0;z-index:0;}
/* The photograph is pinned to the band rather than chained through
   height:100%. The band is shorter than the picture is tall at this width, and
   a percentage height resolves against the grid *area*, which the oversized
   image had already stretched — so the chain gave back the image's natural
   720px and the crop sat too low. Pinning the figure to the absolutely
   positioned row makes the box the band's height whatever the picture is. */
[data-bz-node="loc-hero-photo-row"] .bz-col,[data-bz-node="loc-hero-photo"],
[data-bz-node="loc-hero-photo"] .bz-container{height:100%;min-height:0;}
[data-bz-node="loc-hero-photo"] figure{position:absolute;inset:0;margin:0;}
[data-bz-node="loc-hero-photo"] img{width:100%;height:100%;object-fit:cover;object-position:center;display:block;}
[data-bz-node="loc-hero-inner"]{position:relative;z-index:2;max-width:960px;margin-inline:auto;}
.ss-crumb{display:flex;justify-content:center;gap:8px;flex-wrap:wrap;font:700 11px/1 var(--font-body);letter-spacing:.16em;color:#E2E2E2;margin-bottom:22px;}
.ss-crumb a{color:#E2E2E2;text-decoration:none;}
[data-bz-node="loc-hero-heading"] h1{font:800 44px/1.14 var(--font-heading);letter-spacing:-.01em;color:#fff;margin:0 0 22px;}
[data-bz-node="loc-hero-sub"]{margin-bottom:30px;}
[data-bz-node="loc-hero-sub"] .bz-text{max-width:700px;margin-inline:auto;}
[data-bz-node="loc-hero-sub"] p{font-size:17px;line-height:1.7;color:#E2E2E2;margin:0;}
[data-bz-node="loc-hero-ctas"] .bz-btns{justify-content:center;gap:14px;}
[data-bz-node="loc-hero-ctas"] .bz-btn{min-height:48px;padding:0 26px;font:700 14px/1.7 var(--font-body);}
[data-bz-node="loc-hero-ctas"] .bz-btn--secondary{background:none;border:1px solid #fff;color:#fff;}
[data-bz-node="loc-hero-ctas"] .bz-btn--secondary:hover{background:#fff;color:#141414;}
@media (max-width:640px){
  [data-bz-node="loc-hero-band"]{padding:72px 20px;}
  [data-bz-node="loc-hero-heading"] h1{font-size:30px;}
}
